# No transactions found on 2023-05-17. Let me check what dates are available
from datetime import datetime

dates_found = {}
for t in all_transactions:
    date = datetime.fromisoformat(t['created_at']).date()
    if date not in dates_found:
        dates_found[date] = []
    dates_found[date].append(t)

# Show the most recent dates
sorted_dates = sorted(dates_found.keys(), reverse=True)
print("Most recent transaction dates:")
for date in sorted_dates[:10]:
    print(f"\n{date}:")
    for t in dates_found[date]:
        print(f"  {t['sender']['name']} -> {t['receiver']['name']}: ${t['amount']} ({t['description']})")

# The dinner was yesterday (2023-05-17) but there are no transactions on that date
# The most recent date is 2023-05-11. Let me check transactions around that date
# and search more broadly for restaurant-related transactions

print("Transactions from 2023-05-11:")
for t in all_transactions:
    if datetime.fromisoformat(t['created_at']).date() == datetime(2023, 5, 11).date():
        print(f"Sender: {t['sender']['name']}, Receiver: {t['receiver']['name']}, Amount: {t['amount']}, Desc: {t['description']}")

print("\nAll transactions from May 2023:")
for t in all_transactions:
    date = datetime.fromisoformat(t['created_at']).date()
    if date.year == 2023 and date.month == 5:
        print(f"Date: {date}, Sender: {t['sender']['name']}, Receiver: {t['receiver']['name']}, Amount: {t['amount']}, Desc: {t['description']}")

