# Now I'll get the creation date for each file and prepare the renaming
# Let me collect file info for all files
file_details = []
for file_path in files:
    file_info = apis.file_system.show_file(access_token=access_token, file_path=file_path)
    file_details.append({
        'path': file_path,
        'created_at': file_info['created_at'],
        'filename': file_path.split('/')[-1]
    })

# Show first few files with their creation dates
for detail in file_details[:5]:
    print(f"{detail['filename']} -> Created: {detail['created_at']}")

