# Filter for transactions received by Paul Miller in 2023
received_transactions = []
for trans in transactions_result:
    if trans['receiver']['email'] == 'paul_mill@gmail.com':
        # Check if created_at is in 2023
        created_at = trans['created_at']
        if created_at.startswith('2023'):
            received_transactions.append(trans)

print(f"Received transactions in 2023: {len(received_transactions)}")
for trans in received_transactions:
    print(f"  Transaction {trans['transaction_id']}: {trans['description']} - {trans['like_count']} likes")

total_likes = sum(trans['like_count'] for trans in received_transactions)
print(f"\nTotal likes: {total_likes}")

